  "/": { type: "text/html; charset=utf-8", body: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>cheat-terminal — search your cheat sheets</title>\n<meta name=\"description\" content=\"Search 1392 terminal commands: Linux, PowerShell, Docker and Git. Copy any command with one click.\">\n<link rel=\"stylesheet\" href=\"/styles.css\">\n</head>\n<body>\n<header class=\"topbar\">\n  <div class=\"brand\">\n    <span class=\"brand-mark\">&gt;_</span>\n    <span class=\"brand-name\">cheat-terminal</span>\n    <span class=\"brand-tag\">web</span>\n  </div>\n  <div class=\"search-wrap\">\n    <input id=\"search\" type=\"search\" placeholder=\"Search commands…  (try: docker ps)\" autocomplete=\"off\" spellcheck=\"false\" aria-label=\"Search commands\">\n    <span class=\"search-hint\">live search</span>\n  </div>\n  <a class=\"admin-link\" href=\"/admin\">Admin</a>\n</header>\n\n<main class=\"layout\">\n  <aside class=\"sidebar\" aria-label=\"Categories\">\n    <div class=\"side-title\">Categories</div>\n    <ul id=\"categories\" class=\"cat-list\"></ul>\n    <div class=\"side-title\">Usefulness</div>\n    <div id=\"levels\" class=\"level-list\" role=\"group\" aria-label=\"Filter by usefulness\">\n      <button class=\"level-chip active\" data-level=\"0\">All levels</button>\n      <button class=\"level-chip\" data-level=\"1\"><span class=\"dot dot-essential\"></span>Essential</button>\n      <button class=\"level-chip\" data-level=\"2\"><span class=\"dot dot-common\"></span>Common</button>\n      <button class=\"level-chip\" data-level=\"3\"><span class=\"dot dot-advanced\"></span>Advanced</button>\n    </div>\n    <div class=\"side-note\" id=\"count-note\"></div>\n  </aside>\n\n  <section class=\"results\" aria-label=\"Results\">\n    <div id=\"status\" class=\"status\">Loading…</div>\n    <ul id=\"list\" class=\"result-list\"></ul>\n  </section>\n\n  <aside class=\"detail\" id=\"detail\" aria-label=\"Details\">\n    <div class=\"detail-empty\">Pick a command to see it in full — description, tags and the copy button live here.</div>\n  </aside>\n</main>\n\n<footer class=\"footer\">\n  <span>cheat-terminal web · Linux, PowerShell, Docker, Git · favorites are saved only in your browser</span>\n</footer>\n\n<div id=\"toast\" class=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n<script src=\"/app.js\"></script>\n</body>\n</html>\n" },
